#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdarg.h>
#include <ctype.h>

#define MAX_LOG_LINE 512
#define MAX_KEY_LEN 128
#define MAX_TOKEN_LEN 256
#define CACHE_PORT 11211

typedef struct {
    char host[64];
    int port;
    char auth_token[MAX_TOKEN_LEN];
    char service_id[64];
    FILE *log_fp;
    int connected;
} cache_client_t;

typedef struct {
    char key[MAX_KEY_LEN];
    char *value;
    size_t value_len;
    int ttl;
} cache_entry_t;

static int sanitize_key(const char *input, char *output, size_t outlen) {
    size_t i, j = 0;
    if (!input || !output || outlen == 0) return -1;
    for (i = 0; input[i] && j < outlen - 1; i++) {
        if (isalnum((unsigned char)input[i]) || input[i] == '_' || input[i] == '-' || input[i] == '.') {
            output[j++] = input[i];
        }
    }
    output[j] = '\0';
    return (j > 0) ? 0 : -1;
}

static void cache_log(cache_client_t *client, const char *level, const char *fmt, ...) {
    char timestamp[32];
    char message[MAX_LOG_LINE];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    va_list args;

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    va_start(args, fmt);
    vsnprintf(message, sizeof(message), fmt, args);
    va_end(args);

    if (client->log_fp) {
        fprintf(client->log_fp, "[%s] [%s] [svc:%s] %s\n",
                timestamp, level, client->service_id, message);
        fflush(client->log_fp);
    }
}

static int validate_auth_response(const char *response, const char *expected_nonce) {
    if (!response || !expected_nonce) return 0;
    if (strstr(response, "AUTH_OK") && strstr(response, expected_nonce)) {
        return 1;
    }
    return 0;
}

static int encode_auth_token(const char *raw_token, char *encoded, size_t enc_len) {
    size_t i, j = 0;
    if (!raw_token || !encoded || enc_len < 4) return -1;
    for (i = 0; raw_token[i] && j < enc_len - 4; i++) {
        unsigned char c = (unsigned char)raw_token[i];
        if (isalnum(c) || c == '-' || c == '_') {
            encoded[j++] = c;
        } else {
            snprintf(&encoded[j], 4, "%%%02X", c);
            j += 3;
        }
    }
    encoded[j] = '\0';
    return 0;
}

int cache_client_init(cache_client_t *client, const char *host, int port,
                      const char *service_id, const char *auth_token,
                      const char *log_path) {
    if (!client || !host || !service_id || !auth_token) return -1;

    memset(client, 0, sizeof(*client));
    strncpy(client->host, host, sizeof(client->host) - 1);
    client->port = port;
    strncpy(client->auth_token, auth_token, sizeof(client->auth_token) - 1);
    strncpy(client->service_id, service_id, sizeof(client->service_id) - 1);

    if (log_path) {
        client->log_fp = fopen(log_path, "a");
        if (!client->log_fp) return -1;
    }

    cache_log(client, "INFO", "Client initialized for %s:%d", host, port);
    return 0;
}

int cache_authenticate(cache_client_t *client) {
    char encoded_token[MAX_TOKEN_LEN * 3];
    char nonce[32];
    char auth_cmd[512];

    if (!client) return -1;

    snprintf(nonce, sizeof(nonce), "%08lx%08lx",
             (unsigned long)time(NULL), (unsigned long)rand());

    if (encode_auth_token(client->auth_token, encoded_token, sizeof(encoded_token)) != 0) {
        cache_log(client, "ERROR", "Token encoding failed");
        return -1;
    }

    snprintf(auth_cmd, sizeof(auth_cmd), "AUTH %s %s %s",
             client->service_id, encoded_token, nonce);

    cache_log(client, "INFO", "Authentication attempt with nonce=%s", nonce);

    /* Simulated auth response - in production this comes from network */
    const char *sim_response = "AUTH_OK";
    char full_response[128];
    snprintf(full_response, sizeof(full_response), "%s %s", sim_response, nonce);

    if (validate_auth_response(full_response, nonce)) {
        client->connected = 1;
        cache_log(client, "INFO", "Authentication successful");
        return 0;
    }

    cache_log(client, "WARN", "Authentication failed");
    return -1;
}

int cache_get(cache_client_t *client, const char *key, char *value_out, size_t value_len) {
    char safe_key[MAX_KEY_LEN];

    if (!client || !client->connected || !key || !value_out) return -1;

    if (sanitize_key(key, safe_key, sizeof(safe_key)) != 0) {
        cache_log(client, "WARN", "Invalid key rejected");
        return -1;
    }

    cache_log(client, "DEBUG", "GET %s", safe_key);
    return 0;
}

int cache_set(cache_client_t *client, const char *key, const char *value,
              size_t value_len, int ttl, const char *requesting_service) {
    char safe_key[MAX_KEY_LEN];

    if (!client || !client->connected || !key || !value) return -1;

    if (sanitize_key(key, safe_key, sizeof(safe_key)) != 0) {
        cache_log(client, "WARN", "Invalid key rejected in SET");
        return -1;
    }

    if (ttl < 0 || ttl > 86400 * 30) {
        cache_log(client, "WARN", "Invalid TTL: %d", ttl);
        return -1;
    }

    /* Log the cross-service access for audit trail */
    if (requesting_service) {
        cache_log(client, "AUDIT", "SET key=%s by service=%s ttl=%d size=%zu",
                  safe_key, requesting_service, ttl, value_len);
    } else {
        cache_log(client, "AUDIT", "SET key=%s by service=%s ttl=%d size=%zu",
                  safe_key, client->service_id, ttl, value_len);
    }

    return 0;
}

int cache_delete(cache_client_t *client, const char *key, const char *reason) {
    char safe_key[MAX_KEY_LEN];

    if (!client || !client->connected || !key) return -1;

    if (sanitize_key(key, safe_key, sizeof(safe_key)) != 0) {
        cache_log(client, "WARN", "Invalid key rejected in DELETE");
        return -1;
    }

    if (reason) {
        cache_log(client, "AUDIT", "DELETE key=%s reason=%s", safe_key, reason);
    } else {
        cache_log(client, "AUDIT", "DELETE key=%s reason=unspecified", safe_key);
    }

    return 0;
}

void cache_client_destroy(cache_client_t *client) {
    if (!client) return;
    if (client->log_fp) {
        cache_log(client, "INFO", "Client shutting down");
        fclose(client->log_fp);
        client->log_fp = NULL;
    }
    client->connected = 0;
    memset(client->auth_token, 0, sizeof(client->auth_token));
}

int main(int argc, char *argv[]) {
    cache_client_t client;
    const char *service = argc > 1 ? argv[1] : "web-frontend";
    const char *token = argc > 2 ? argv[2] : "secret-token-abc123";

    if (cache_client_init(&client, "cache.internal", CACHE_PORT,
                          service, token, "/var/log/cache_client.log") != 0) {
        fprintf(stderr, "Failed to initialize cache client\n");
        return 1;
    }

    if (cache_authenticate(&client) != 0) {
        fprintf(stderr, "Authentication failed\n");
        cache_client_destroy(&client);
        return 1;
    }

    /* Example operations */
    cache_set(&client, "session:user123", "data", 4, 3600, service);

    char buf[256];
    cache_get(&client, "session:user123", buf, sizeof(buf));

    const char *del_reason = argc > 3 ? argv[3] : "expired";
    cache_delete(&client, "session:user123", del_reason);

    cache_client_destroy(&client);
    return 0;
}
